const DASHBOARD_HTML = "<!doctype html>\n<html lang=\"id\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"theme-color\" content=\"#f3f6fb\">\n<title>Dashboard Monitoring SBML Kementerian/Lembaga</title>\n<style>\n:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,'Segoe UI',Arial,sans-serif;color:#18253e;background:#f2f6fb;--primary:#5638f5;--green:#16a34a;--red:#e11d65;--amber:#d97706;--border:#dde6f0;--muted:#6c7b94}\n*{box-sizing:border-box}body{margin:0;min-width:320px}button,input,select{font:inherit}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.48}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #a69bff;outline-offset:2px}\n.topbar{background:#fff;border-bottom:1px solid var(--border);box-shadow:0 2px 8px #283c5b09}.bar-inner{max-width:1400px;padding:18px 24px;margin:auto;display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.identity{display:flex;align-items:center;gap:13px}.logo{width:56px;height:56px;border:1px solid #d9def8;border-radius:16px;background:linear-gradient(135deg,#eef4ff,#f1ecff);display:grid;place-items:center;box-shadow:0 3px 8px #283a6710;overflow:hidden;padding:6px}.logo img{width:100%;height:100%;object-fit:contain;display:block}.identity h1{font-size:22px;letter-spacing:-.7px;margin:0;font-weight:800}.identity h1 span{color:var(--primary)}.sub{color:var(--muted);font-size:12px;margin-top:3px}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{display:inline-flex;justify-content:center;align-items:center;gap:7px;border:1px solid #d9e1ed;background:#fff;color:#273b57;border-radius:12px;padding:10px 13px;font-size:13px;font-weight:700;white-space:nowrap;text-decoration:none}.btn.primary{color:#fff;background:var(--primary);border-color:var(--primary);box-shadow:0 3px 8px #5638f535}.btn.danger{color:#be174b;background:#fff5f8;border-color:#f6cede}.btn.ghost{border-color:transparent;background:#f1f4f9}.btn:hover:not(:disabled){filter:brightness(.97)}.btn.small{padding:7px 10px;font-size:12px}\n.container{max-width:1400px;margin:0 auto;padding:22px 24px 42px}.notice{border:1px solid #d9e1f0;background:#f7f9ff;border-radius:12px;margin-bottom:18px;padding:11px 15px;display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:13px;color:#4b5871}.notice strong{color:#273d60}.notice.error{background:#fff5f6;border-color:#f6ccd5;color:#991b40}.notice.ok{background:#f0fdf4;border-color:#c7eed2;color:#166534}.close-note{margin-left:auto;border:0;background:transparent;color:inherit;font-size:18px}\n.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin-bottom:19px}.stat{background:#fff;border:1px solid var(--border);border-radius:16px;padding:17px 20px;box-shadow:0 2px 3px #1d31460b}.stat .caption{font-size:12px;color:var(--muted);font-weight:650}.stat .number{font-weight:800;font-size:30px;margin:5px 0 1px;letter-spacing:-1px}.stat .foot{font-size:11px;color:#8b98aa}.stat .number.good{color:var(--green)}.stat .number.bad{color:var(--red)}.stat .number.other{color:var(--amber)}\n.topgrid{display:grid;grid-template-columns:1.12fr .98fr;gap:18px;margin-bottom:18px}.panel{background:white;border:1px solid var(--border);border-radius:17px;box-shadow:0 2px 3px #1d31460d}.chart-panel{padding:20px 22px 15px}.panel-title{font-weight:800;font-size:12px;letter-spacing:.55px;color:#607797;text-transform:uppercase;margin:0}.chart-inner{min-height:280px;display:grid;grid-template-columns:minmax(240px,1fr) 130px;align-items:center;gap:10px}.chart{width:100%;max-height:300px}.chart-key{display:flex;flex-direction:column;gap:13px}.legend{display:flex;align-items:center;gap:8px;font-weight:700;font-size:13px}.dot{display:inline-block;flex:none;width:12px;height:12px;border-radius:50%}.legend strong{margin-left:auto}.chart-info{border-top:1px solid #f0f2f6;color:#6a7890;font-size:12px;padding-top:10px}.decision-cards{display:flex;flex-direction:column;gap:12px}.decision-card{--accent:#64748b;background:#fff;border:1px solid var(--border);border-left:5px solid var(--accent);border-radius:14px;box-shadow:0 2px 3px #1d31460a;padding:17px 20px;display:flex;align-items:center;justify-content:space-between;gap:12px;color:var(--accent);text-align:left;min-height:75px}.decision-card .name{font-size:14px;font-weight:750}.decision-card .count{font-size:24px;font-weight:800;color:#17213a}.decision-card .count small{color:#728198;font-size:11px;font-weight:500}.decision-card.selected{background:#f8f7ff;border-color:var(--accent)}\n.filter-panel{padding:14px 17px;margin-bottom:17px}.filters{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.filter-label{font-size:11px;letter-spacing:.4px;font-weight:800;color:#647b9c;margin-right:5px}.chip{border:0;border-radius:11px;background:#f2f5fa;padding:9px 13px;color:#344b69;font-size:12px;font-weight:700}.chip.active{background:var(--primary);color:#fff;box-shadow:0 2px 5px #5134f338}\n.table-panel{overflow:hidden}.table-head{padding:19px 20px 14px}.table-head h2{font-size:17px;margin:0 0 5px}.table-head p{margin:0;color:var(--muted);font-size:12px}.tools{padding:0 20px 15px;display:grid;grid-template-columns:minmax(260px,1fr) repeat(3,minmax(140px,190px)) auto;gap:9px}.field{width:100%;min-width:0;border:1px solid #d6e0ec;border-radius:11px;background:#fff;color:#1b2c48;padding:11px 12px;font-size:13px}.field::placeholder{color:#91a0b2}.tools .btn{justify-self:stretch}.info-line{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0 20px 11px;color:#708098;font-size:12px;flex-wrap:wrap}.table-scroll{overflow:auto;max-height:570px;border-top:1px solid #e9edf4}table{border-collapse:collapse;width:100%;min-width:1100px;font-size:12.5px}th,td{padding:13px 11px;vertical-align:top;border-bottom:1px solid #e8edf4;text-align:left;line-height:1.5}th{position:sticky;top:0;z-index:1;background:#f7f9fc;color:#566b88;font-size:11px;font-weight:800;white-space:nowrap}td{color:#293a53}td:first-child,th:first-child{text-align:center}td:nth-child(2){font-weight:750;min-width:150px}td:nth-child(5){min-width:185px}td:nth-child(8){min-width:125px}td:last-child{white-space:nowrap}.status-badge{display:inline-block;padding:5px 8px;border-radius:8px;font-weight:750;font-size:11px}.status-badge.approved{background:#e8f9ee;color:#15803d}.status-badge.rejected{background:#ffedf2;color:#be185d}.status-badge.other{background:#fff5e6;color:#a16207}.row-actions{white-space:nowrap}.row-actions button{border:0;background:transparent;color:#4b43dd;font-weight:700;padding:3px}.row-actions button.delete{color:#c02d5c}.empty{padding:35px;text-align:center;color:#6c7b94}.pager{display:flex;gap:10px;justify-content:flex-end;align-items:center;padding:13px 18px;font-size:12px;color:#73819b}.footer{font-size:12px;color:#7d8b9d;margin-top:17px}.hidden,[hidden]{display:none!important}\n.modal-backdrop{position:fixed;inset:0;z-index:30;background:#15223888;display:grid;place-items:center;padding:16px}.modal{width:min(690px,100%);max-height:95vh;overflow:auto;border-radius:18px;background:#fff;box-shadow:0 20px 65px #10233a44}.modal-title{padding:19px 23px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center}.modal-title h2{font-size:19px;margin:0}.form-grid{padding:20px 23px;display:grid;grid-template-columns:1fr 1fr;gap:12px}.form-grid label{font-weight:700;font-size:12px;color:#51617a;display:flex;flex-direction:column;gap:6px}.form-grid label.wide{grid-column:1/-1}.form-grid textarea{resize:vertical;min-height:65px}.modal-foot{padding:15px 23px;border-top:1px solid var(--border);display:flex;justify-content:flex-end;gap:9px}.kbd{display:inline-block;background:#eaf0f9;border-radius:6px;padding:2px 5px;font:inherit}\n@media(max-width:1000px){.tools{grid-template-columns:repeat(3,minmax(0,1fr))}.tools input{grid-column:1/-1}.topgrid{grid-template-columns:1fr}.decision-cards{display:grid;grid-template-columns:repeat(3,1fr)}.decision-card{padding:15px}.decision-card .count{font-size:21px}}\n@media(max-width:680px){.bar-inner,.container{padding-left:14px;padding-right:14px}.stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.stat{padding:13px}.stat .number{font-size:25px}.decision-cards{grid-template-columns:1fr}.chart-inner{grid-template-columns:1fr}.chart{max-height:280px}.chart-key{display:flex;flex-direction:row;flex-wrap:wrap;gap:12px}.chart-info{margin-top:10px}.tools{grid-template-columns:1fr 1fr}.tools input{grid-column:1/-1}.tools .btn{grid-column:1/-1}.form-grid{grid-template-columns:1fr}.form-grid label.wide{grid-column:1}.identity h1{font-size:19px}}\n@media print{.actions,.tools,.filters,.row-actions,.pager,.notice,.footer,.modal-backdrop{display:none!important}.container{max-width:none}.table-scroll{max-height:none;overflow:visible}table{min-width:0;font-size:9px}th{position:static}.topgrid{grid-template-columns:1fr 1fr}.decision-cards{display:block}.decision-card{margin-bottom:5px}}\n\n/* Palet pastel: biru muda dan ungu muda. Struktur dan menu dashboard tetap. */\n:root{background:#eff5ff;--border:#dce5fa;--primary:#6547df;--muted:#667895}\nbody{background:linear-gradient(135deg,#e6f4ff 0%,#eff5ff 40%,#f2ebff 75%,#e8f2ff 100%);background-attachment:fixed}\n.topbar{background:linear-gradient(105deg,#eaf6ff 0%,#f1edff 65%,#e7f0ff 100%);border-bottom:1px solid #dce6fb;box-shadow:0 4px 18px #6f6aab19}\n.logo{background:linear-gradient(135deg,#dcecff,#e8dfff);border-color:#d1d7fc}\n.panel{background:#fff;box-shadow:0 5px 17px #7b80ad13;border-color:#dfe4fa}\n.stat{background:#edf7ff;border-color:#d8eafa;box-shadow:0 4px 14px #889ac017}\n.stat:nth-child(2){background:#eff9f4;border-color:#d3ecde}\n.stat:nth-child(3){background:#fff1f7;border-color:#f7dde8}\n.stat:nth-child(4){background:#f1ebff;border-color:#dfd4fb}\n.chart-panel{background:linear-gradient(150deg,#ffffff 60%,#eff2ff)}\n.decision-card{background:#f8faff;border-color:#e2e7fa;border-left-color:var(--accent)}\n.decision-card:nth-child(1){background:#f0edff}\n.decision-card:nth-child(2){background:#effaf4}\n.decision-card:nth-child(3){background:#fff1f7}\n.decision-card:nth-child(4){background:#f0f5ff}\n.decision-card.selected{background:#eae7ff;box-shadow:0 0 0 2px #b7a9ff32}\n.filter-panel{background:linear-gradient(90deg,#ecf6ff,#f3ecff)}\n.table-head{background:linear-gradient(90deg,#f5faff,#f6f1ff)}\n.chip{background:#e9f0ff}\n.field{border-color:#d9e2f5}\nth{background:#eff3ff;color:#526889}\ntbody tr:nth-child(even){background:#f9fbff}\n.btn.ghost{background:#e8ecff}\n.notice{background:#edf5ff}\n@media print{body{background:white!important}}\n\n/* Identitas instansi: header formal dan logo transparan. Area lain tetap mengikuti layout sebelumnya. */\n.topbar{position:relative}\n.topbar::before{content:\"\";position:absolute;left:0;right:0;top:0;height:3px;background:linear-gradient(90deg,#2c65c6,#7556cc,#c5b5ed)}\n.bar-inner{padding-top:16px;padding-bottom:16px;gap:18px}\n.identity{align-items:center;min-width:0;gap:16px;flex:1 1 590px}\n.logo,.logo{width:70px;height:76px;flex:none;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;overflow:visible}\n.logo img{width:100%;height:100%;object-fit:contain;display:block;filter:drop-shadow(0 2px 3px rgba(23,42,86,.12))}\n.identity-copy{min-width:0}\n.institution{color:#4d6390;font-size:10px;letter-spacing:1.4px;font-weight:800;margin-bottom:5px}\n.identity h1{font-size:clamp(19px,2vw,25px);line-height:1.23;letter-spacing:-.65px;font-weight:800;margin:0;color:#162944;max-width:920px}\n.identity h1 span{color:#6649da}\n.sub{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:12px;line-height:1.5;margin-top:6px}\n.subtitle-label{font-weight:550;color:#546b92}\n.subtitle-divider{color:#a7abd4}\n#updateLabel{color:#607594}\n@media(max-width:680px){.bar-inner{padding-top:16px;padding-bottom:16px}.identity{gap:11px;flex-basis:100%}.logo{width:52px;height:64px}.identity h1{font-size:18px}.institution{font-size:9px;letter-spacing:.65px}.sub{font-size:11px;gap:5px}.subtitle-divider{display:none}.subtitle-label{width:100%}.actions{justify-content:flex-end;width:100%}}\n</style>\n</head>\n<body>\n<header class=\"topbar\"><div class=\"bar-inner\">\n<div class=\"identity\"><div class=\"logo\" ><img src=\"./logo-kemenkeu-transparent.png\" alt=\"Logo Kementerian Keuangan\"></div><div class=\"identity-copy\"><div class=\"institution\">KEMENTERIAN KEUANGAN REPUBLIK INDONESIA</div><h1 id=\"appTitle\">Dashboard Monitoring <span>SBML</span> Kementerian/Lembaga</h1><div class=\"sub\"><span class=\"subtitle-label\" id=\"subtitleLabel\">Pemantauan Usulan Standar Biaya Masukan Lainnya</span><span class=\"subtitle-divider\" aria-hidden=\"true\">·</span><span id=\"updateLabel\">Memuat data...</span></div></div></div>\n<div class=\"actions\"><a id=\"openSheet\" href=\"#\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn hidden\">↗ Buka Sheet</a><button class=\"btn primary\" type=\"button\" id=\"refresh\">↻ Refresh</button></div>\n</div></header>\n<main class=\"container\">\n<div id=\"notice\" class=\"notice\" role=\"status\"><strong id=\"noticeTitle\">Memuat</strong><span id=\"noticeText\">Aplikasi sedang menyiapkan data.</span><button class=\"close-note\" id=\"closeNotice\" type=\"button\" title=\"Tutup pesan\">×</button></div>\n<section class=\"stats\" aria-label=\"Statistik SBML\">\n<div class=\"stat\"><div class=\"caption\">Total Usulan SBML</div><div class=\"number\" id=\"statTotal\">0</div><div class=\"foot\">Semua surat/usulan</div></div>\n<div class=\"stat\"><div class=\"caption\">Disetujui</div><div class=\"number good\" id=\"statApproved\">0</div><div class=\"foot\">Status keputusan disetujui</div></div>\n<div class=\"stat\"><div class=\"caption\">Ditolak</div><div class=\"number bad\" id=\"statRejected\">0</div><div class=\"foot\">Status keputusan ditolak</div></div>\n<div class=\"stat\"><div class=\"caption\">Proses / Status Lain</div><div class=\"number other\" id=\"statOther\">0</div><div class=\"foot\">Belum diputuskan atau kategori lain</div></div>\n</section>\n<section class=\"topgrid\">\n<div class=\"panel chart-panel\"><h2 class=\"panel-title\" id=\"chartTitle\">PERBANDINGAN KEPUTUSAN: DISETUJUI / DITOLAK</h2><div class=\"chart-inner\"><svg id=\"pie\" class=\"chart\" viewBox=\"0 0 320 300\" role=\"img\" aria-label=\"Diagram donat jumlah usulan disetujui dan ditolak\"><circle cx=\"150\" cy=\"145\" r=\"95\" stroke=\"#ebeff6\" stroke-width=\"53\" fill=\"none\"></circle><text x=\"150\" y=\"138\" text-anchor=\"middle\" font-size=\"33\" font-weight=\"800\" fill=\"#17233d\">0</text><text x=\"150\" y=\"158\" text-anchor=\"middle\" font-size=\"12\" fill=\"#657995\">keputusan</text></svg><div class=\"chart-key\"><div class=\"legend\"><i class=\"dot\" style=\"background:var(--green)\"></i>Disetujui <strong id=\"legendApproved\">0</strong></div><div class=\"legend\"><i class=\"dot\" style=\"background:var(--red)\"></i>Ditolak <strong id=\"legendRejected\">0</strong></div></div></div><div class=\"chart-info\" id=\"chartNote\">Hanya keputusan Disetujui dan Ditolak yang diperhitungkan dalam grafik pie.</div></div>\n<div class=\"decision-cards\"><button type=\"button\" class=\"decision-card\" style=\"--accent:#5638f5\" data-decision=\"all\"><span class=\"name\">● Semua Usulan SBML</span><span class=\"count\"><span id=\"cardAll\">0</span> <small>usulan</small></span></button><button type=\"button\" class=\"decision-card\" style=\"--accent:#16a34a\" data-decision=\"approved\"><span class=\"name\">● Disetujui</span><span class=\"count\"><span id=\"cardApproved\">0</span> <small>usulan</small></span></button><button type=\"button\" class=\"decision-card\" style=\"--accent:#e11d65\" data-decision=\"rejected\"><span class=\"name\">● Ditolak</span><span class=\"count\"><span id=\"cardRejected\">0</span> <small>usulan</small></span></button><button type=\"button\" class=\"decision-card\" style=\"--accent:#d97706\" data-decision=\"other\"><span class=\"name\">● Proses / Status Lain</span><span class=\"count\"><span id=\"cardOther\">0</span> <small>usulan</small></span></button></div>\n</section>\n<div class=\"panel filter-panel\"><div class=\"filters\"><span class=\"filter-label\">FILTER STATUS</span><button class=\"chip active\" data-decision=\"all\" type=\"button\">Semua <span id=\"chipAll\">0</span></button><button class=\"chip\" data-decision=\"approved\" type=\"button\">Disetujui <span id=\"chipApproved\">0</span></button><button class=\"chip\" data-decision=\"rejected\" type=\"button\">Ditolak <span id=\"chipRejected\">0</span></button><button class=\"chip\" data-decision=\"other\" type=\"button\">Proses / Lainnya <span id=\"chipOther\">0</span></button><button class=\"btn small ghost\" id=\"reset\" type=\"button\">× Reset filter</button></div></div>\n<section class=\"panel table-panel\" aria-label=\"Matriks inventarisasi SBML\"><div class=\"table-head\"><h2 id=\"tableTitle\">Matriks Inventarisasi SBML</h2><p>Data bersumber dari Google Sheets · Gunakan <b>Tambah Usulan</b> untuk membuka spreadsheet dan memasukkan data.</p></div>\n<div class=\"tools\"><input class=\"field\" id=\"search\" type=\"search\" placeholder=\"Cari Nama K/L, nomor surat, perihal, jenis SBML...\" aria-label=\"Pencarian seluruh kolom\"><select class=\"field\" id=\"yearFilter\" aria-label=\"Filter tahun\"><option value=\"\">Semua Tahun</option></select><select class=\"field\" id=\"klFilter\" aria-label=\"Filter nama K/L\"><option value=\"\">Semua K/L</option></select><select class=\"field\" id=\"typeFilter\" aria-label=\"Filter jenis SBML\"><option value=\"\">Semua Jenis SBML</option></select><button class=\"btn primary\" id=\"addRecord\" type=\"button\">＋ Tambah Usulan</button></div>\n<div class=\"info-line\"><span id=\"tableInfo\">Menampilkan 0 data</span><div class=\"actions\"><button class=\"btn small\" id=\"exportCsv\" type=\"button\">↓ Ekspor CSV</button><button class=\"btn small\" id=\"exportJson\" type=\"button\">↓ JSON</button><button class=\"btn small\" id=\"print\" type=\"button\">⎙ Cetak</button></div></div>\n<div class=\"table-scroll\"><table><thead><tr><th>No</th><th>Nama KL</th><th>Tahun</th><th>No Surat / Tgl</th><th>Perihal</th><th>Surat Menkeu / Tgl</th><th>Karakteristik K/L</th><th>Jenis SBML</th><th>Status</th><th class=\"row-actions\">Aksi</th></tr></thead><tbody id=\"tbody\"></tbody></table><div id=\"empty\" class=\"empty hidden\">Tidak ada data yang sesuai pencarian atau filter.</div></div>\n<div class=\"pager\"><button class=\"btn small\" type=\"button\" id=\"prevPage\">← Sebelumnya</button><span id=\"pageLabel\">Halaman 1</span><button class=\"btn small\" type=\"button\" id=\"nextPage\">Berikutnya →</button></div>\n</section><div class=\"footer\">Dashboard SBML · Sumber data: Google Sheets · Pembaruan usulan dilakukan pada spreadsheet, lalu pilih Refresh di dashboard.</div>\n</main>\n<script>\n'use strict';\nconst APP_CONFIG={\n  title:'Dashboard Monitoring SBML Kementerian/Lembaga',\n  subtitle:'Pemantauan Usulan Standar Biaya Masukan Lainnya',\n  chartTitle:'PERBANDINGAN KEPUTUSAN: DISETUJUI / DITOLAK',\n  tableTitle:'Matriks Inventarisasi SBML'\n};\nconst HEADERS=['No','Nama KL','Tahun','No Surat / Tgl','Perihal','Surat Menkeu / Tgl','Karakteristik K/L','Jenis SBML','Status'];\nconst KEYS=['no','nama_kl','tahun','no_surat_tgl','perihal','surat_menkeu_tgl','karakteristik_kl','jenis_sbml','status'];\nconst $=id=>document.getElementById(id),trim=v=>String(v??'').trim();\ndocument.title=APP_CONFIG.title+' | Monitoring Usulan';\nconst keyword='SBML',position=APP_CONFIG.title.indexOf(keyword);if(position>=0){const accent=document.createElement('span');accent.textContent=keyword;$('appTitle').replaceChildren(document.createTextNode(APP_CONFIG.title.slice(0,position)),accent,document.createTextNode(APP_CONFIG.title.slice(position+keyword.length)))}else $('appTitle').textContent=APP_CONFIG.title;\n$('subtitleLabel').textContent=APP_CONFIG.subtitle;\n$('chartTitle').textContent=APP_CONFIG.chartTitle;\n$('tableTitle').textContent=APP_CONFIG.tableTitle;\n$('updateLabel').textContent='Memuat data...';\n\nconst esc=v=>trim(v).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nlet rows=[],decision='all',page=1,sheetUrl='',loaded=false;\nconst PAGE_SIZE=20;\nconst normKey=k=>trim(k).toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');\nfunction toRecord(raw,index){const mapped={};for(const [k,v] of Object.entries(raw||{}))mapped[normKey(k)]=trim(v);\n const get=(...names)=>{for(const name of names){const v=mapped[normKey(name)];if(v!==undefined&&v!=='')return v}return ''};\n return {no:get('no','nomor')||String(index+1),nama_kl:get('nama_kl','nama kl','nama k/l','nama k l'),tahun:get('tahun'),no_surat_tgl:get('no_surat_tgl','no surat / tgl'),perihal:get('perihal'),surat_menkeu_tgl:get('surat_menkeu_tgl','surat menkeu / tgl'),karakteristik_kl:get('karakteristik_kl','karakteristik k/l'),jenis_sbml:get('jenis_sbml','jenis sbml'),status:get('status')||'Belum Ada Status'};\n}\nfunction decisionOf(value){const s=trim(value).toLowerCase().replace(/\\s+/g,' ');if(/^disetujui(?:\\b|$)/.test(s)||/^persetujuan\\b/.test(s))return 'approved';if(/^ditolak(?:\\b|$)/.test(s)||/^penolakan\\b/.test(s)||/^tidak\\s+(?:dapat\\s+)?disetujui\\b/.test(s))return 'rejected';return 'other'}\nconst totalBy=(arr,k)=>arr.filter(r=>decisionOf(r.status)===k).length;\nfunction chart(arr){const accepted=totalBy(arr,'approved'),rejected=totalBy(arr,'rejected'),decided=accepted+rejected,r=95,circ=2*Math.PI*r,colors=['#16a34a','#e11d65'];\n $('legendApproved').textContent=accepted;$('legendRejected').textContent=rejected;\n let offset=0;const parts=[accepted,rejected].map((n,index)=>({n,index})).filter(x=>x.n>0).map(({n,index})=>{const out=`<circle cx=\"150\" cy=\"145\" r=\"${r}\" fill=\"none\" stroke=\"${colors[index]}\" stroke-width=\"53\" stroke-dasharray=\"${(n/decided*circ).toFixed(4)} ${(circ-n/decided*circ).toFixed(4)}\" stroke-dashoffset=\"${(-offset/decided*circ).toFixed(4)}\" transform=\"rotate(-90 150 145)\"></circle>`;offset+=n;return out}).join('');\n $('pie').innerHTML=`<circle cx=\"150\" cy=\"145\" r=\"${r}\" fill=\"none\" stroke=\"#e8edf5\" stroke-width=\"53\"></circle>${parts}<text x=\"150\" y=\"140\" text-anchor=\"middle\" font-size=\"32\" font-weight=\"800\" fill=\"#17233d\">${decided?Math.round(accepted/decided*100)+'%':'—'}</text><text x=\"150\" y=\"160\" text-anchor=\"middle\" font-size=\"12\" fill=\"#657995\">${decided} keputusan</text>`;\n $('chartNote').textContent=`${decided} usulan dengan keputusan Disetujui/Ditolak; ${totalBy(arr,'other')} usulan dalam proses atau status lain tidak masuk penyebut persentase. Grafik mengikuti filter pencarian, tahun, K/L, dan jenis SBML.`;\n}\nfunction filtersWithoutDecision(){const q=trim($('search').value).toLocaleLowerCase('id-ID'),y=$('yearFilter').value,k=$('klFilter').value,t=$('typeFilter').value;return rows.filter(r=>(!y||r.tahun===y)&&(!k||r.nama_kl===k)&&(!t||r.jenis_sbml===t)&&(!q||KEYS.some(key=>trim(r[key]).toLocaleLowerCase('id-ID').includes(q))))}\nfunction filtered(){const base=filtersWithoutDecision();return decision==='all'?base:base.filter(r=>decisionOf(r.status)===decision)}\nfunction optionList(id,values,label){const el=$(id),old=el.value,arr=[...new Set(values.map(trim).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'id'));el.replaceChildren(new Option(label,''),...arr.map(v=>new Option(v,v)));el.value=arr.includes(old)?old:''}\nfunction setupFilters(){optionList('yearFilter',rows.map(x=>x.tahun),'Semua Tahun');optionList('klFilter',rows.map(x=>x.nama_kl),'Semua K/L');optionList('typeFilter',rows.map(x=>x.jenis_sbml),'Semua Jenis SBML')}\nfunction render(){const base=filtersWithoutDecision(),view=filtered(),a=totalBy(base,'approved'),r=totalBy(base,'rejected'),o=totalBy(base,'other');\n $('statTotal').textContent=rows.length;$('statApproved').textContent=totalBy(rows,'approved');$('statRejected').textContent=totalBy(rows,'rejected');$('statOther').textContent=totalBy(rows,'other');\n for(const [id,n] of [['All',base.length],['Approved',a],['Rejected',r],['Other',o]]){$('card'+id).textContent=n;$('chip'+id).textContent=n}\n chart(base);document.querySelectorAll('[data-decision]').forEach(b=>{const active=b.dataset.decision===decision;b.classList.toggle('selected',active&&b.classList.contains('decision-card'));b.classList.toggle('active',active&&b.classList.contains('chip'));b.setAttribute('aria-pressed',String(active))});\n const totalPages=Math.max(1,Math.ceil(view.length/PAGE_SIZE));page=Math.min(Math.max(page,1),totalPages);\n const start=(page-1)*PAGE_SIZE,slice=view.slice(start,start+PAGE_SIZE);\n $('tbody').innerHTML=slice.map(x=>{const st=decisionOf(x.status);return `<tr>${KEYS.map(k=>k==='status'?`<td><span class=\"status-badge ${st}\">${esc(x.status)}</span></td>`:`<td>${esc(x[k])||'—'}</td>`).join('')}<td class=\"row-actions\"><span style=\"color:#7181a3\">Google Sheets</span></td></tr>`}).join('');\n $('empty').classList.toggle('hidden',view.length!==0);$('empty').textContent=!loaded?'Data Google Sheets belum tersedia. Klik Refresh untuk mencoba kembali.':'Tidak ada data yang sesuai pencarian atau filter.';\n $('tableInfo').textContent=`Menampilkan ${view.length?start+1:0}–${Math.min(start+PAGE_SIZE,view.length)} dari ${view.length} usulan cocok (total ${rows.length})`;\n $('pageLabel').textContent=`Halaman ${page} dari ${totalPages}`;$('prevPage').disabled=page<=1;$('nextPage').disabled=page>=totalPages;\n}\nfunction notify(title,text,kind=''){const el=$('notice');el.className='notice'+(kind?' '+kind:'');$('noticeTitle').textContent=title;$('noticeText').textContent=text;el.classList.remove('hidden')}\nasync function load(){const button=$('refresh');button.disabled=true;button.textContent='↻ Memuat...';\n try{const response=await fetch('/api/sbml',{cache:'no-store'});let result;try{result=await response.json()}catch{throw Error('Respons API bukan JSON')}if(!response.ok)throw Error(result.error||'Gagal mengambil data (HTTP '+response.status+')');if(result.source!=='Google Sheets'||!Array.isArray(result.data))throw Error('Sumber data bukan Google Sheets');\n rows=result.data.map(toRecord).filter(r=>r.nama_kl);loaded=true;sheetUrl=result.sheetUrl||'';$('openSheet').classList.toggle('hidden',!sheetUrl);if(sheetUrl)$('openSheet').href=sheetUrl;\n $('updateLabel').textContent='Diperbarui '+new Date().toLocaleString('id-ID');page=1;setupFilters();render();notify('Google Sheets terhubung',`${rows.length} data berhasil dimuat dari spreadsheet. Tambah atau ubah data melalui Google Sheets.`, 'ok');\n }catch(e){rows=[];loaded=false;sheetUrl='';$('openSheet').classList.add('hidden');$('updateLabel').textContent='Koneksi data belum tersedia';setupFilters();render();notify('Gagal memuat Google Sheets',e.message+'. Tidak menampilkan data lokal atau demonstrasi.','error')}\n finally{button.disabled=false;button.textContent='↻ Refresh'}}\nfunction csvCell(v){let s=trim(v);if(/^[=+\\-@\\t\\r]/.test(s))s=\"'\"+s;return '\"'+s.replace(/\"/g,'\"\"')+'\"'}\nfunction download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500)}\nfunction exportCSV(){const content='\\uFEFF'+[HEADERS,...filtered().map(r=>KEYS.map(k=>r[k]))].map(row=>row.map(csvCell).join(',')).join('\\r\\n');download(content,'matriks-sbml-'+new Date().toISOString().slice(0,10)+'.csv','text/csv;charset=utf-8')}\nfunction exportJSON(){download(JSON.stringify(filtered().map(r=>Object.fromEntries(KEYS.map(k=>[k,r[k]]))),null,2),'matriks-sbml-'+new Date().toISOString().slice(0,10)+'.json','application/json;charset=utf-8')}\nfunction addRecord(){if(sheetUrl){window.open(sheetUrl,'_blank','noopener,noreferrer')}else notify('Google Sheets belum tersedia','Hubungkan data Google Sheets dan klik Refresh sebelum menambahkan usulan.','error')}\n$('refresh').addEventListener('click',load);$('closeNotice').addEventListener('click',()=>$('notice').classList.add('hidden'));\nfor(const id of ['search','yearFilter','klFilter','typeFilter'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=1;render()});\ndocument.querySelectorAll('[data-decision]').forEach(b=>b.addEventListener('click',()=>{decision=b.dataset.decision;page=1;render()}));\n$('reset').addEventListener('click',()=>{decision='all';$('search').value='';for(const id of ['yearFilter','klFilter','typeFilter'])$(id).value='';page=1;render()});\n$('exportCsv').addEventListener('click',exportCSV);$('exportJson').addEventListener('click',exportJSON);$('print').addEventListener('click',()=>window.print());\n$('prevPage').addEventListener('click',()=>{page--;render()});$('nextPage').addEventListener('click',()=>{page++;render()});\n$('addRecord').addEventListener('click',addRecord);\nload();\n</script></body></html>";
const LOGO_KEMENKEU_B64 = "";
// Google Sheets read-only backend, Cloudflare Workers + static assets.
// Secrets: SHEET_ID, GOOGLE_CLIENT_EMAIL, GOOGLE_PRIVATE_KEY.
const FIELDS = ['no','nama_kl','tahun','no_surat_tgl','perihal','surat_menkeu_tgl','karakteristik_kl','jenis_sbml','status'];
function b64url(data){const bytes=typeof data==='string'?new TextEncoder().encode(data):new Uint8Array(data);let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
async function tokenFor(env){const now=Math.floor(Date.now()/1000),header=b64url(JSON.stringify({alg:'RS256',typ:'JWT'})),payload=b64url(JSON.stringify({iss:env.GOOGLE_CLIENT_EMAIL,scope:'https://www.googleapis.com/auth/spreadsheets.readonly',aud:'https://oauth2.googleapis.com/token',iat:now,exp:now+3600}));const unsigned=header+'.'+payload;const pem=env.GOOGLE_PRIVATE_KEY.replace(/\\n/g,'\n').replace(/-----BEGIN PRIVATE KEY-----|-----END PRIVATE KEY-----|\s/g,'');const key=await crypto.subtle.importKey('pkcs8',Uint8Array.from(atob(pem),v=>v.charCodeAt(0)),{name:'RSASSA-PKCS1-v1_5',hash:'SHA-256'},false,['sign']);const sig=await crypto.subtle.sign('RSASSA-PKCS1-v1_5',key,new TextEncoder().encode(unsigned));const jwt=unsigned+'.'+b64url(sig);const response=await fetch('https://oauth2.googleapis.com/token',{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded'},body:new URLSearchParams({grant_type:'urn:ietf:params:oauth:grant-type:jwt-bearer',assertion:jwt})});if(!response.ok)throw new Error('Gagal autentikasi Google ('+response.status+')');const json=await response.json();if(!json.access_token)throw new Error('Google tidak memberikan token');return json.access_token}
export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname==='/logo-kemenkeu-transparent.png'&&request.method==='GET')return new Response(Uint8Array.from(atob(LOGO_KEMENKEU_B64),c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/png','Cache-Control':'public, max-age=86400','X-Content-Type-Options':'nosniff'}});if(url.pathname==='/api/config-check'){const required=['SHEET_ID','GOOGLE_CLIENT_EMAIL','GOOGLE_PRIVATE_KEY'];const missing=required.filter(k=>typeof env[k]!=='string'||!env[k].trim());return Response.json({app:'Dashboard SBML',build:'diagnostik-20261009',configured:missing.length===0,missingVariables:missing,requiredCount:required.length,configuredCount:required.length-missing.length,notes:'Hanya nama variabel; tidak menampilkan nilainya.'},{headers:{'Cache-Control':'no-store'}})}if(url.pathname==='/api/sbml'){if(request.method!=='GET')return Response.json({error:'Metode tidak diizinkan'},{status:405,headers:{Allow:'GET'}});if(!env.SHEET_ID||!env.GOOGLE_CLIENT_EMAIL||!env.GOOGLE_PRIVATE_KEY)return Response.json({error:'Google Sheets belum dikonfigurasi',check:'/api/config-check'},{status:503,headers:{'Cache-Control':'no-store'}});try{const accessToken=await tokenFor(env);const range=env.SHEET_RANGE||'SBML!A:I';const endpoint='https://sheets.googleapis.com/v4/spreadsheets/'+encodeURIComponent(env.SHEET_ID)+'/values/'+encodeURIComponent(range);const response=await fetch(endpoint,{headers:{Authorization:'Bearer '+accessToken}});if(!response.ok)throw new Error('Gagal membaca Google Sheets ('+response.status+')');const payload=await response.json();const records=payload.values||[];if(records.length===0)return Response.json({data:[],source:'Google Sheets',sheetUrl:'https://docs.google.com/spreadsheets/d/'+encodeURIComponent(env.SHEET_ID)+'/edit'},{headers:{'Cache-Control':'no-store'}});const header=records[0].map(v=>String(v).trim().toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,''));if(!header.includes('nama_kl')||!header.includes('status'))throw new Error('Header Sheet harus memuat Nama KL dan Status');const aliases={karakteristik_kl:['karakteristik_kl','karakteristik_k_l'],nama_kl:['nama_kl','nama_k_l']};const data=records.slice(1).filter(row=>row.some(v=>String(v??'').trim())).map(values=>Object.fromEntries(FIELDS.map(field=>{const index=(aliases[field]||[field]).map(key=>header.indexOf(key)).find(idx=>idx>=0);return [field,index===undefined?'':String(values[index]??'')]}))).filter(item=>item.nama_kl.trim());return Response.json({data,source:'Google Sheets',sheetUrl:'https://docs.google.com/spreadsheets/d/'+encodeURIComponent(env.SHEET_ID)+'/edit'},{headers:{'Cache-Control':'no-store'}})}catch(e){return Response.json({error:String(e.message||'Gagal memuat Sheets')},{status:502,headers:{'Cache-Control':'no-store'}})}}if((url.pathname==='/'||url.pathname==='/index.html')&&request.method==='GET')return new Response(DASHBOARD_HTML,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});return new Response('Not Found',{status:404,headers:{'Content-Type':'text/plain; charset=utf-8'}})}};
